# Python 3 example implementation
import itertools
def f(N, L, X, T): 
    a=list(itertools.product([0,1],repeat=N))
    for i in range(len(a)):
        if sum(a[i])==0:
            return 0
        count=0
        for j in range(N):
            if a[i][j]==1:
                count+=1
                if count>1 or (X[j]!=0 and T[j]!=0):
                    return 0
                elif X[j]==0 and T[j]==1:
                    count=1
                else:
                    count=0
    return 1

